//! Dish photo finders (the `DishImageFinder` port).
//!
//! - [`UnsplashFinder`]: searches Unsplash for the dish and hotlinks the photo,
//!   following the Unsplash API guidelines: images are loaded from Unsplash's
//!   CDN (`urls.raw` with its `ixid` kept), each use is reported to the
//!   photo's `download_location`, and the photographer is credited.
//! - An AI image generator would be another `DishImageFinder`: it would store
//!   the generated bytes under `media/` (via `FileStorage`) and return that URL
//!   with `ImageSource::Generated`.
//!
//! Configure with `[media.stock]` (`provider = "unsplash"`, `access_key` from
//! `FEAST__MEDIA__STOCK__ACCESS_KEY`). Without a key, no finder runs and the
//! apps show generated cuisine art for dishes without a photo.

use std::time::Duration;

use async_trait::async_trait;
use feast_application::ports::{DishImageFinder, DishQuery, FoundImage};
use feast_application::{AppError, AppResult};
use feast_domain::media::{stock_query, ImageSource};
use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
pub struct UnsplashConfig {
    /// Unsplash "Access Key" of a registered app.
    pub access_key: String,
    /// Your Unsplash app name, used in attribution links (`utm_source`).
    #[serde(default = "default_app_name")]
    pub app_name: String,
    #[serde(default = "default_api")]
    pub api_url: String,
    /// Width of the hotlinked image (pixels).
    #[serde(default = "default_width")]
    pub width: u32,
}

fn default_app_name() -> String {
    "feast".into()
}
fn default_api() -> String {
    "https://api.unsplash.com".into()
}
fn default_width() -> u32 {
    640
}

pub struct UnsplashFinder {
    cfg: UnsplashConfig,
    http: reqwest::Client,
}

impl UnsplashFinder {
    pub fn new(cfg: UnsplashConfig) -> AppResult<Self> {
        if cfg.access_key.trim().is_empty() {
            return Err(AppError::internal("media.stock.access_key is empty"));
        }
        let http = reqwest::Client::builder().timeout(Duration::from_secs(10)).build().map_err(|e| AppError::internal(format!("http client: {e}")))?;
        Ok(Self { cfg, http })
    }
}

#[derive(Debug, Deserialize)]
struct SearchResponse {
    #[serde(default)]
    results: Vec<Photo>,
}

#[derive(Debug, Deserialize)]
struct Photo {
    urls: Urls,
    links: Links,
    user: Photographer,
    #[serde(default)]
    alt_description: Option<String>,
    #[serde(default)]
    description: Option<String>,
    #[serde(default)]
    tags: Vec<Tag>,
    #[serde(default)]
    premium: Option<bool>,
    #[serde(default)]
    plus: Option<bool>,
}

#[derive(Debug, Deserialize)]
struct Urls {
    raw: String,
}

#[derive(Debug, Deserialize)]
struct Links {
    #[serde(default)]
    download_location: Option<String>,
}

#[derive(Debug, Deserialize)]
struct Photographer {
    name: String,
    username: String,
}

#[derive(Debug, Deserialize)]
struct Tag {
    #[serde(default)]
    title: String,
}

/// Words of the dish name worth matching (3+ letters).
fn dish_words(dish: &str) -> Vec<String> {
    stock_query(dish, None).split(|c: char| !c.is_alphanumeric()).filter(|w| w.len() >= 3).map(|w| w.to_ascii_lowercase()).collect()
}

/// Pick the free photo whose description or tags mention the most words of
/// the dish name. No photo mentions the dish → none (better generated art
/// than a picture of the wrong food).
fn pick<'a>(photos: &'a [Photo], dish: &str) -> Option<&'a Photo> {
    let words = dish_words(dish);
    photos
        .iter()
        .filter(|p| !p.premium.unwrap_or(false) && !p.plus.unwrap_or(false) && p.urls.raw.starts_with("https://images.unsplash.com/"))
        .map(|p| {
            let text = format!(
                "{} {} {}",
                p.alt_description.as_deref().unwrap_or(""),
                p.description.as_deref().unwrap_or(""),
                p.tags.iter().map(|t| t.title.as_str()).collect::<Vec<_>>().join(" ")
            )
            .to_ascii_lowercase();
            (words.iter().filter(|w| text.contains(w.as_str())).count(), p)
        })
        .filter(|(score, _)| *score > 0)
        // Highest score; earliest (most relevant) result wins ties.
        .fold(None::<(usize, &Photo)>, |best, (s, p)| match best {
            Some((bs, _)) if bs >= s => best,
            _ => Some((s, p)),
        })
        .map(|(_, p)| p)
}

/// Hotlink URL: Unsplash's raw URL (keeping its `ixid`) plus sizing params.
fn hotlink(raw: &str, width: u32) -> String {
    let sep = if raw.contains('?') { '&' } else { '?' };
    format!("{raw}{sep}auto=format&fit=crop&w={width}&q=80")
}

#[async_trait]
impl DishImageFinder for UnsplashFinder {
    fn enabled(&self) -> bool {
        true
    }

    async fn find(&self, q: &DishQuery) -> AppResult<Option<FoundImage>> {
        let query = stock_query(&q.dish, q.cuisine.as_deref());
        if query.is_empty() {
            return Ok(None);
        }
        let url = format!("{}/search/photos", self.cfg.api_url.trim_end_matches('/'));
        let res = self
            .http
            .get(&url)
            .query(&[("query", query.as_str()), ("per_page", "15"), ("orientation", "landscape"), ("content_filter", "high")])
            .header("Authorization", format!("Client-ID {}", self.cfg.access_key))
            .header("Accept-Version", "v1")
            .send()
            .await
            .map_err(|e| AppError::unavailable(format!("Unsplash: {e}")))?;
        if res.status() == reqwest::StatusCode::FORBIDDEN || res.status() == reqwest::StatusCode::TOO_MANY_REQUESTS {
            return Err(AppError::unavailable("Unsplash rate limit reached"));
        }
        if !res.status().is_success() {
            return Err(AppError::unavailable(format!("Unsplash search failed: {}", res.status())));
        }
        let body: SearchResponse = res.json().await.map_err(|e| AppError::unavailable(format!("Unsplash: {e}")))?;
        let Some(p) = pick(&body.results, &q.dish) else { return Ok(None) };
        // Guidelines: report the use of the photo (not a real download).
        if let Some(dl) = &p.links.download_location {
            let ping = self.http.get(dl).header("Authorization", format!("Client-ID {}", self.cfg.access_key)).header("Accept-Version", "v1");
            tokio::spawn(async move {
                let _ = ping.send().await;
            });
        }
        Ok(Some(FoundImage {
            url: hotlink(&p.urls.raw, self.cfg.width),
            credit: Some(format!("{} · Unsplash (unsplash.com/@{}?utm_source={}&utm_medium=referral)", p.user.name, p.user.username, self.cfg.app_name)),
            source: ImageSource::Stock,
        }))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn photos() -> Vec<Photo> {
        serde_json::from_value(serde_json::json!([
            { "urls": { "raw": "https://plus.unsplash.com/premium_photo-1?ixid=a" }, "links": {}, "user": { "name": "P", "username": "p" },
              "alt_description": "masala dosa on a plate", "premium": true, "plus": true },
            { "urls": { "raw": "https://images.unsplash.com/photo-2?ixid=b" }, "links": { "download_location": "https://api.unsplash.com/photos/2/download" },
              "user": { "name": "A", "username": "a" }, "alt_description": "a mountain at dawn" },
            { "urls": { "raw": "https://images.unsplash.com/photo-3?ixid=c" }, "links": {}, "user": { "name": "B", "username": "b" },
              "alt_description": "crispy dosa with chutney", "tags": [{ "title": "masala" }] },
            { "urls": { "raw": "https://images.unsplash.com/photo-4?ixid=d" }, "links": {}, "user": { "name": "C", "username": "c" },
              "description": "dosa" }
        ]))
        .unwrap()
    }

    #[test]
    fn picks_free_photo_matching_the_dish() {
        let ps = photos();
        let p = pick(&ps, "Masala dosa").unwrap();
        assert_eq!(p.user.username, "b"); // premium skipped; 2 words beat 1
        assert!(pick(&ps, "Pavlova").is_none()); // nothing mentions it → no photo
    }

    #[test]
    fn hotlinks_keep_ixid() {
        assert_eq!(hotlink("https://images.unsplash.com/photo-3?ixid=c", 640), "https://images.unsplash.com/photo-3?ixid=c&auto=format&fit=crop&w=640&q=80");
        assert_eq!(hotlink("https://images.unsplash.com/photo-3", 480), "https://images.unsplash.com/photo-3?auto=format&fit=crop&w=480&q=80");
    }
}
